function generateOceanMesh(time, windDirection, waveIntensity):
    for each vertex (x, z) in grid:
        y = 0
        for each waveComponent in waveSpectrum:
            k = waveVector (direction * frequency)
            A = waveComponent.amplitude
            w = waveComponent.frequency
            phi = waveComponent.phase
            // Gerstner wave
            y += A * cos(dot(k, (x,z)) - w*time + phi)
            x -= k.x * (A/w) * sin(dot(k, (x,z)) - w*time + phi)
            z -= k.z * (A/w) * sin(dot(k, (x,z)) - w*time + phi)
        // Add noise for details
        y += perlinNoise(x*scale, z*scale, time) * noiseAmplitude
    return mesh
